    structures("Figure 1 2-Methylcyclohexanone and its two enolates", [
        ("CC1CCCCC1=O", "2-Methylcyclohexanone"), ("CC1CCCC=C1[O-]", "Enolate from C6", "less substituted"), ("CC1=C([O-])CCCC1", "Enolate from C2", "more substituted")]),
