         wrong=[("Its conjugate acid is stronger than the ketone", "If that were true, the equilibrium would favor the ketone, not the enolate."),
                ("It is a nucleophile that adds to the ketone's C=O", "LDA is too bulky to add to C=O easily. It acts as a base."),
                ("It reacts with methyl iodide before the ketone", "The enolate is formed before CH<sub>3</sub>I is added.")],
